def sha(path: str) -> str:
    p = ROOT / path
    if not p.is_file():
        return ''
    h = hashlib.sha256()
    with p.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def main():
    header, *lines = RECORDS.strip().splitlines()
    fields = header.split('|')
    rows = []
    for line in lines:
        values = line.split('|')
        if len(values) != len(fields):
            raise ValueError(f'{len(values)} fields instead of {len(fields)}: {line[:100]}')
        row = dict(zip(fields, values))
        row['retrieved_date'] = '2026-10-18' if row['source_id'] != 'WINNIPEG-RFP-2023' else '2026-10-21'
        row['sha256_if_known'] = sha(row['local_path']) if row['local_path'] else ''
        rows.append(row)
    columns = ['source_id', 'title', 'publisher', 'publication_date', 'retrieved_date',
               'doc_type', 'url', 'local_path', 'sha256_if_known', 'geography', 'period',
               'topics', 'document_status', 'evidence_role', 'useful_facts', 'scope_limits',
               'still_useful_for_redecision']
    with (OUT / 'source_index.csv').open('w', encoding='utf-8-sig', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=columns)
        writer.writeheader()
        writer.writerows(rows)
    print(f'wrote {len(rows)} sources; {sum(bool(r["sha256_if_known"]) for r in rows)} with local hashes')


if __name__ == '__main__':
    main()
